-- TaskHub initial schema.
--
-- Portable on purpose: runs unchanged on PostgreSQL 14+ and on H2 in PostgreSQL mode
-- (used by the integration-test profile). That is why UUIDs are generated by the
-- application, enums are VARCHAR + CHECK instead of native types, and no PL/pgSQL,
-- triggers or extensions are used.

CREATE TABLE users (
    id            uuid                     NOT NULL,
    email         varchar(255)             NOT NULL,
    password_hash varchar(100)             NOT NULL,
    display_name  varchar(120)             NOT NULL,
    role          varchar(20)              NOT NULL,
    enabled       boolean                  NOT NULL DEFAULT true,
    created_at    timestamp with time zone NOT NULL,
    updated_at    timestamp with time zone NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_role CHECK (role IN ('ADMIN', 'MANAGER', 'MEMBER'))
);

CREATE TABLE refresh_tokens (
    id         uuid                     NOT NULL,
    user_id    uuid                     NOT NULL,
    token_hash varchar(64)              NOT NULL,
    family_id  uuid                     NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked    boolean                  NOT NULL DEFAULT false,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT uk_refresh_tokens_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX idx_refresh_tokens_user ON refresh_tokens (user_id);
CREATE INDEX idx_refresh_tokens_family ON refresh_tokens (family_id);

CREATE TABLE projects (
    id          uuid                     NOT NULL,
    code        varchar(32)              NOT NULL,
    name        varchar(160)             NOT NULL,
    description varchar(4000),
    status      varchar(20)              NOT NULL,
    owner_id    uuid                     NOT NULL,
    version     bigint                   NOT NULL DEFAULT 0,
    created_at  timestamp with time zone NOT NULL,
    updated_at  timestamp with time zone NOT NULL,
    CONSTRAINT pk_projects PRIMARY KEY (id),
    CONSTRAINT uk_projects_code UNIQUE (code),
    CONSTRAINT fk_projects_owner FOREIGN KEY (owner_id) REFERENCES users (id),
    CONSTRAINT ck_projects_status CHECK (status IN ('PLANNED', 'ACTIVE', 'ON_HOLD', 'COMPLETED', 'ARCHIVED'))
);

CREATE INDEX idx_projects_owner ON projects (owner_id);
CREATE INDEX idx_projects_status ON projects (status);

CREATE TABLE project_members (
    id          uuid                     NOT NULL,
    project_id  uuid                     NOT NULL,
    user_id     uuid                     NOT NULL,
    member_role varchar(20)              NOT NULL,
    added_at    timestamp with time zone NOT NULL,
    CONSTRAINT pk_project_members PRIMARY KEY (id),
    CONSTRAINT uk_project_members UNIQUE (project_id, user_id),
    CONSTRAINT fk_project_members_project FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
    CONSTRAINT fk_project_members_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT ck_project_members_role CHECK (member_role IN ('OWNER', 'CONTRIBUTOR', 'VIEWER'))
);

CREATE INDEX idx_project_members_user ON project_members (user_id);

CREATE TABLE tasks (
    id              uuid                     NOT NULL,
    project_id      uuid                     NOT NULL,
    title           varchar(200)             NOT NULL,
    description     varchar(8000),
    status          varchar(20)              NOT NULL,
    priority        varchar(20)              NOT NULL,
    due_date        date,
    assignee_id     uuid,
    estimated_hours numeric(6, 2),
    version         bigint                   NOT NULL DEFAULT 0,
    created_at      timestamp with time zone NOT NULL,
    updated_at      timestamp with time zone NOT NULL,
    CONSTRAINT pk_tasks PRIMARY KEY (id),
    CONSTRAINT fk_tasks_project FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE CASCADE,
    CONSTRAINT fk_tasks_assignee FOREIGN KEY (assignee_id) REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT ck_tasks_status CHECK (status IN ('TODO', 'IN_PROGRESS', 'BLOCKED', 'DONE')),
    CONSTRAINT ck_tasks_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT ck_tasks_estimated_hours CHECK (estimated_hours IS NULL OR estimated_hours >= 0)
);

CREATE INDEX idx_tasks_project_status ON tasks (project_id, status);
CREATE INDEX idx_tasks_assignee ON tasks (assignee_id);
CREATE INDEX idx_tasks_due_date ON tasks (due_date);
CREATE INDEX idx_tasks_title ON tasks (title);
